// PackBits decode into a caller buffer of `cap` bytes. Returns bytes written.
static inline uint32_t ff_unpack_n(const uint8_t* src, uint32_t len, uint8_t* dst, uint32_t cap) {
  uint32_t si = 0, di = 0;
  while (si < len && di < cap) {
    int8_t n = (int8_t)src[si++];
    if (n >= 0) {                       // 1+n literal bytes
      for (int k = 0; k <= n && di < cap && si < len; k++) dst[di++] = src[si++];
    } else if (n != -128) {             // 1-n repeats of one byte
      uint8_t v = src[si++];
      for (int k = 0; k < 1 - n && di < cap; k++) dst[di++] = v;
    }
  }
  return di;
}
static inline uint32_t ff_unpack(const uint8_t* src, uint32_t len, uint8_t* dst) {
  return ff_unpack_n(src, len, dst, FF_SCREEN_BYTES);
}
